/* Kustîrk (the ring game): the hand looks sold in the shop.
   =====================================================================
   TO ADD A LOOK: add one entry to SETS (name in 4 languages, price in AG).
   A drawn look gives its colours: k = skin (5 colours, left to right), f = finger tops (3), n = nails (2),
   w = wrist (2), cr = skin lines, sl = [sleeve, sleeve dark] or none, deco = "henna" | "bolts" | "stitch" |
   "stars" | "sparkle" | "flag" | "gold". price 0 = free for everyone. Only this file changes.
   kh_photo = the photo hands (free). kh_custom = the player's own three photos (they upload them in the
   Kustîrk lobby: "📷 my hands").
   ===================================================================== */
(function(){
var IMG={"fist": "data:image/webp;base64,", "open": "data:image/webp;base64,", "ring": "data:image/webp;base64,", "ringx": "data:image/webp;base64,"};
var SKIN={k:["#d9946c","#f4c4a0","#fbd6b8","#eab18a","#c98560"],f:["#ffe3cc","#f6c39e","#d48e66"],n:["#ffeee4","#eebfa8"],w:["#e8b08a","#d49470"],cr:"#b97853"};
var SETS={
  kh_photo:{name:["دەستێن ڕاستەقینە","دەستی ڕاستەقینە","أيدٍ حقيقية","Real hands"],price:0,photo:1},
  kh_soft:{name:["کێشای","کێشراو","مرسومة","Drawn"],price:0,c:SKIN},
  kh_gold:{name:["دەستکێشێن زێڕ","دەستکێشی زێڕ","قفازات ذهبية","Gold gloves"],price:150,deco:"gold",
    c:{k:["#8a5a12","#e0b040","#fff1a8","#d9a530","#7a4e0e"],f:["#fff6c8","#f2c94c","#a8761a"],n:["#fffbe8","#f2d27a"],w:["#c99a2e","#8a5f1c"],cr:"#7a5212"}},
  kh_henna:{name:["خەنە","خەنە","حناء","Henna"],price:200,deco:"henna",c:SKIN},
  kh_kurd:{name:["کوردستان","کوردستان","كردستان","Kurdistan"],price:250,deco:"flag",c:SKIN,sl:["#278e43","#14602a"]},
  kh_robot:{name:["ڕۆبۆت","ڕۆبۆت","روبوت","Robot"],price:300,deco:"bolts",
    c:{k:["#5d6b78","#aab8c4","#e6eef4","#9fb0bf","#4f5c68"],f:["#f2f7fb","#b9c7d3","#6c7a86"],n:["#7fe3ff","#2bb6e6"],w:["#8494a3","#56636f"],cr:"#45525e"}},
  kh_zombie:{name:["زۆمبی","زۆمبی","زومبي","Zombie"],price:350,deco:"stitch",
    c:{k:["#4f7a3a","#8fc06a","#b5dc8e","#7fb05a","#45702f"],f:["#c9eaa8","#94c46c","#5f8f45"],n:["#3d4a2c","#2a3320"],w:["#7aa858","#4d7a36"],cr:"#3e6129"}},
  kh_galaxy:{name:["گەلەستێرک","گەلەستێرە","مجرة","Galaxy"],price:400,deco:"stars",
    c:{k:["#2a1260","#6d28d9","#a78bfa","#7c3aed","#2a0f5a"],f:["#d8c8ff","#8b5cf6","#4c1d95"],n:["#ffffff","#c4b5fd"],w:["#5b21b6","#2e1065"],cr:"#2e1065"}},
  kh_diamond:{name:["ئەلماس","ئەڵماس","ألماس","Diamond"],price:500,deco:"sparkle",rare:true,
    c:{k:["#5fa8c9","#bfe8f7","#f2fbff","#a6dcf0","#4f98b9"],f:["#ffffff","#cdeef9","#7fbcd6"],n:["#ffffff","#d8f3ff"],w:["#9fd3e8","#5fa8c9"],cr:"#3f86a6"}},
  kh_custom:{name:["📷 وێنەیێن دەستێن تە","📷 وێنەی دەستەکانت","📷 صور يديك","📷 Your own hands"],price:1000,custom:1}
};
var N=0;
function ring(big){var id="kr"+(++N);
  return '<svg viewBox="0 0 100 100"><defs><linearGradient id="'+id+'a" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff2b8"/><stop offset=".35" stop-color="#f2c24a"/><stop offset=".7" stop-color="#b5801c"/><stop offset="1" stop-color="#f7d77a"/></linearGradient>'+
  '<radialGradient id="'+id+'b" cx="40%" cy="35%" r="70%"><stop offset="0" stop-color="#ffffff"/><stop offset=".5" stop-color="#d8f1ff"/><stop offset="1" stop-color="#7fb2d6"/></radialGradient></defs>'+
  '<ellipse cx="50" cy="66" rx="30" ry="24" fill="none" stroke="#7a5212" stroke-width="13"/><ellipse cx="50" cy="66" rx="30" ry="24" fill="none" stroke="url(#'+id+'a)" stroke-width="9"/>'+
  '<path d="M38 40h24l7 9-19 20-19-20z" fill="url(#'+id+'b)" stroke="#5f8fb3" stroke-width="2" stroke-linejoin="round"/><path d="M38 40l12 29M62 40L50 69M31 49h38" stroke="#8bbad9" stroke-width="1.2" fill="none"/>'+
  (big?'<g fill="#fff"><path d="M78 22l2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/><path d="M20 30l1.4 4 4 1.4-4 1.4-1.4 4-1.4-4-4-1.4 4-1.4z"/></g>':'')+'</svg>'}
function inner(svg){return svg.replace(/^<svg[^>]*>/,"").replace(/<\/svg>$/,"")}
var XMARK='<g opacity=".92"><path d="M20 30l60 80M80 30l-60 80" stroke="#ff2d2d" stroke-width="13" stroke-linecap="round"/></g>';
// a drawn hand. kind: fist | open | ring | ringbig | ringx
function drawn(s,kind,team){var c=s.c,id="kh"+(++N),g;
  var D='<defs><linearGradient id="'+id+'k" x1="0" y1="0" x2="1" y2="0">'+c.k.map(function(x,i){return'<stop offset="'+[0,.25,.55,.85,1][i]+'" stop-color="'+x+'"/>'}).join("")+'</linearGradient>'+
   '<radialGradient id="'+id+'f" cx="50%" cy="30%" r="70%"><stop offset="0" stop-color="'+c.f[0]+'"/><stop offset=".55" stop-color="'+c.f[1]+'"/><stop offset="1" stop-color="'+c.f[2]+'"/></radialGradient>'+
   '<radialGradient id="'+id+'n" cx="50%" cy="35%" r="60%"><stop offset="0" stop-color="'+c.n[0]+'"/><stop offset="1" stop-color="'+c.n[1]+'"/></radialGradient>'+
   '<linearGradient id="'+id+'w" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="'+c.w[0]+'"/><stop offset="1" stop-color="'+c.w[1]+'"/></linearGradient>'+
   '<filter id="'+id+'b" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="1.3"/></filter>'+
   '<filter id="'+id+'s" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="3"/></filter></defs>';
  var K='url(#'+id+'k)',F='url(#'+id+'f)',NL='url(#'+id+'n)',B='url(#'+id+'b)',S='url(#'+id+'s)',cr=c.cr,b=D;
  var sl=s.sl||team;
  b+='<path d="M33 140V100c0-6 4-9 17-9s17 3 17 9v40z" fill="url(#'+id+'w)"/>';
  if(sl){b+='<path d="M28 140l3-30h38l3 30z" fill="'+sl[0]+'"/><rect x="28" y="106" width="44" height="8" rx="4" fill="'+sl[1]+'"/>';
    if(s.deco==="flag")b+='<rect x="31" y="114" width="38" height="8" fill="#e2231a"/><rect x="31" y="122" width="38" height="8" fill="#fff"/><circle cx="50" cy="126" r="3.4" fill="#fcbf09"/>'}
  var open=kind!=="fist";
  if(!open){
    b+='<ellipse cx="50" cy="104" rx="26" ry="6" fill="#000" opacity=".25" filter="'+S+'"/>';
    b+='<path d="M19 58c0-20 12-32 31-32s31 12 31 32v24c0 14-11 22-25 22H43c-14 0-24-8-24-22z" fill="'+K+'"/>';
    [20,35.5,51,66].forEach(function(x,i){var y=i===0||i===3?40:34,w=15.5,h=34;
      b+='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="7.6" fill="'+F+'"/><ellipse cx="'+(x+w/2)+'" cy="'+(y+7)+'" rx="4.6" ry="3.2" fill="#fff" opacity=".35" filter="'+B+'"/>'+
        '<path d="M'+(x+3.5)+' '+(y+h*.46)+'q'+(w/2-3.5)+' 2.4 '+(w-7)+' 0" stroke="'+cr+'" stroke-width="1" fill="none" opacity=".55"/>'});
    [35.5,51,66].forEach(function(x){b+='<path d="M'+x+' 40v32" stroke="'+cr+'" stroke-width="2" opacity=".5" filter="'+B+'"/>'});
    b+='<path d="M14 78c0-8 7-12 17-12h26c8 0 11 4 11 8s-3 8-11 8H31c-10 0-17-1-17-4z" fill="#000" opacity=".22" filter="'+S+'" transform="translate(0 3)"/>';
    b+='<path d="M15 76c0-8 7-12 17-12h25c8 0 11 4 11 8s-3 8-11 8H32c-10 0-17 0-17-4z" fill="'+F+'"/>';
    b+='<ellipse cx="59" cy="71.5" rx="7.5" ry="5.2" fill="'+NL+'"/><path d="M54 70q5-2.6 10 0" stroke="#fff" stroke-width="1.2" fill="none" opacity=".7"/>';
    b+='<path d="M30 92q20 6 40-2" stroke="'+cr+'" stroke-width="1.2" fill="none" opacity=".45"/>';
    if(s.deco==="henna")b+='<g fill="none" stroke="#9a3b14" stroke-width="1.3" opacity=".85"><circle cx="50" cy="88" r="5"/><circle cx="50" cy="88" r="2" fill="#9a3b14"/><path d="M40 88q10-9 20 0M38 94q12 8 24 0"/></g>';
  }else{
    b+='<ellipse cx="50" cy="106" rx="28" ry="6" fill="#000" opacity=".25" filter="'+S+'"/>';
    [[24,16,12,46,-14],[37,5,12.5,54,-4],[50.5,7,12.5,52,5],[63.5,18,11.5,42,15]].forEach(function(f){var x=f[0],y=f[1],w=f[2],h=f[3],r=f[4],cx=x+w/2,by=y+h+6;
      b+='<g transform="rotate('+r+' '+cx+' '+by+')"><rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+(h+10)+'" rx="'+(w/2)+'" fill="'+K+'"/>'+
        '<rect x="'+(x+2)+'" y="'+(y+1.5)+'" width="'+(w-4)+'" height="9" rx="4" fill="'+NL+'" opacity=".6"/>'+
        '<path d="M'+(x+2.5)+' '+(y+h*.38)+'q'+(w/2-2.5)+' 1.8 '+(w-5)+' 0M'+(x+2.5)+' '+(y+h*.68)+'q'+(w/2-2.5)+' 1.8 '+(w-5)+' 0" stroke="'+cr+'" stroke-width=".9" fill="none" opacity=".6"/>'+
        (s.deco==="henna"?'<path d="M'+(x+3)+' '+(y+h*.2)+'h'+(w-6)+'M'+(x+3)+' '+(y+h*.25)+'h'+(w-6)+'" stroke="#9a3b14" stroke-width="1" opacity=".85"/>':'')+
        '<ellipse cx="'+cx+'" cy="'+(y+16)+'" rx="2.4" ry="9" fill="#fff" opacity=".22" filter="'+B+'"/></g>'});
    b+='<path d="M21 62c0-8 9-12 29-12s29 4 29 12v22c0 14-11 22-25 22h-8c-14 0-25-8-25-22z" fill="'+K+'"/>';
    b+='<ellipse cx="50" cy="76" rx="18" ry="13" fill="#fff" opacity=".18" filter="'+S+'"/>';
    b+='<path d="M24 74c-8-4-17-12-16-20 1-5 7-5 11-1l14 14c3 3 2 8-1 9z" fill="'+K+'"/>';
    b+='<path d="M28 68q14 5 30 0M30 80q12 4 26-1M44 60q-5 12 0 26" stroke="'+cr+'" stroke-width="1.1" fill="none" opacity=".5"/>';
    if(s.deco==="henna")b+='<g fill="none" stroke="#9a3b14" stroke-width="1.3" opacity=".9"><circle cx="50" cy="78" r="9"/><circle cx="50" cy="78" r="4.5"/><circle cx="50" cy="78" r="1.8" fill="#9a3b14"/><path d="M41 78h-6M65 78h-6M50 69v-6M50 87v6M43 71l-4-4M57 71l4-4M43 85l-4 4M57 85l4 4"/></g>';
  }
  if(s.deco==="bolts")[[30,90],[70,90],[30,62],[70,62]].forEach(function(p){b+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="2.4" fill="#56636f"/><circle cx="'+(p[0]-.6)+'" cy="'+(p[1]-.6)+'" r="1" fill="#fff" opacity=".7"/>'});
  if(s.deco==="stitch")b+='<path d="M28 84l26-14M33 75l4 6M40 71l4 6M47 67l4 6" stroke="#2a3320" stroke-width="1.6" fill="none" stroke-linecap="round"/>';
  if(s.deco==="stars")[[30,70,1.4],[62,64,1],[44,88,1.2],[70,84,1.6],[38,58,.9],[56,96,1]].forEach(function(p){b+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="'+p[2]+'" fill="#fff"/>'});
  if(s.deco==="sparkle"||s.deco==="gold")[[32,60],[66,80],[46,94]].forEach(function(p){b+='<path d="M'+p[0]+' '+(p[1]-5)+'l1.3 3.7 3.7 1.3-3.7 1.3-1.3 3.7-1.3-3.7-3.7-1.3 3.7-1.3z" fill="#fff"/>'});
  if(kind==="ring")b+='<svg x="30" y="54" width="40" height="40" viewBox="0 0 100 100">'+inner(ring())+'</svg>';
  if(kind==="ringbig"||kind==="ringx")b+='<svg x="4" y="30" width="92" height="92" viewBox="0 0 100 100">'+inner(ring(true))+'</svg>';
  if(kind==="ringx")b+=XMARK;
  return '<svg viewBox="0 0 100 140" aria-hidden="true">'+b+'</svg>'}
// a photo hand (the free one, or the player's own); team = a coloured band under it in the game
function photo(src,kind,team,x){
  return '<svg viewBox="0 0 100 140" aria-hidden="true">'+(team?'<rect x="22" y="134" width="56" height="6" rx="3" fill="'+team[0]+'"/>':'')+
    '<image href="'+src+'" x="0" y="0" width="100" height="'+(team?132:140)+'" preserveAspectRatio="xMidYMax meet"/>'+(x?XMARK:'')+'</svg>'}
function hand(key,kind,team,custom){var s=SETS[key]||SETS.kh_photo;
  if(s.custom&&custom){var src=kind==="fist"?custom.f:kind==="open"?custom.o:custom.r;
    if(src)return photo(src,kind,team,kind==="ringx")}
  if(s.custom||s.photo){var k=kind==="fist"?"fist":kind==="open"?"open":kind==="ringx"?"ringx":"ring";return photo(IMG[k],kind,team,false)}
  return drawn(s,kind,team)}
function el(html){var d=document.createElement("div");d.innerHTML=html;var s=d.firstChild;s.style.cssText="width:100%;max-width:240px;height:auto;display:block;margin:0 auto";return s}
function preview(k){var s=SETS[k]||{};
  if(s.custom)return el('<svg viewBox="0 0 240 150"><rect width="240" height="150" rx="14" fill="#1b2235"/><g transform="translate(70 18)"><rect x="0" y="16" width="100" height="72" rx="14" fill="#2f3b57" stroke="#ffd23f" stroke-width="4"/><circle cx="50" cy="52" r="22" fill="#0b1020" stroke="#ffd23f" stroke-width="4"/><circle cx="50" cy="52" r="10" fill="#59a8ff"/><rect x="30" y="6" width="32" height="14" rx="5" fill="#ffd23f"/></g><text x="120" y="136" text-anchor="middle" font-family="system-ui,sans-serif" font-weight="800" font-size="18" fill="#ffd23f">✊ 🖐 💍</text></svg>');
  var w='<svg viewBox="0 0 240 150"><rect width="240" height="150" rx="14" fill="#0e0e14"/>';
  [["fist",8],["open",84],["ring",160]].forEach(function(p){w+='<svg x="'+p[1]+'" y="6" width="72" height="140" viewBox="0 0 100 140">'+inner(hand(k,p[0]))+'</svg>'});
  return el(w+'</svg>')}
window.KSH={sets:SETS,hand:hand,ring:ring};
if(!window.AG||!AG.addPack)return;
AG.addPack({type:"kshand",def:"kh_photo",items:SETS,
  title:["💍 دەستێن کوستیرکێ","💍 دەستەکانی ئەنگوستیلە","💍 أيدي محيبس","💍 Ring game hands"],
  desc:["شێوازێ دەستێن تە ل یاریا کوستیرکێ و ستۆدیۆیا لایڤێ. «📷 وێنەیێن دەستێن تە»: پشتی کڕینێ، ل یاریا کوستیرکێ ← 📷 دەستێن من، وێنەیێن خۆ دانێ.",
        "شێوازی دەستەکانت لە یاری ئەنگوستیلە و ستۆدیۆی لایڤ. «📷 وێنەی دەستەکانت»: دوای کڕین، لە یاری ئەنگوستیلە ← 📷 دەستەکانم، وێنەکانت دابنێ.",
        "شكل يديك في لعبة محيبس واستوديو البث. «📷 صور يديك»: بعد الشراء، ضع صورك من لعبة محيبس ← 📷 يداي.",
        "Your hands in the ring game and the live studio. \"📷 Your own hands\": after buying, add your photos in the ring game → 📷 My hands."],
  preview:preview});
})();
